  } catch (err) {
    if (err instanceof z.ZodError) return next(validationError());
    next(err);
  }
});

router.delete('/:id', (req, res, next) => {
  const id = Number(req.params.id);
  if (!getView(id)) return next(notFound('Saved view not found.'));
  deleteView(id);
  res.status(204).end();
});

