import { describe, it, expect, beforeAll } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

// Isolate the DB in a temp directory for this test file.
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'bm-imp-'));
process.env.BOOKMARKS_DATA_DIR = tmp;

let importExport;
let bookmarks;

beforeAll(async () => {
  importExport = await import('../../src/services/importExport.js');
  bookmarks = await import('../../src/models/bookmarks.js');
});

const SAMPLE = `<!DOCTYPE NETSCAPE-Bookmark-file-1>
<DL><p>
  <DT><H3>Work</H3>
  <DL><p>
    <DT><A HREF="https://example.com/a" ADD_DATE="1600000000" TAGS="report">Alpha</A>
    <DT><A HREF="https://example.com/b/" ADD_DATE="1600000100">Beta</A>
  </DL><p>
  <DT><A HREF="https://example.com/c" ADD_DATE="1600000200">Gamma</A>
</DL><p>`;

describe('Netscape import parsing', () => {
  it('maps folders and TAGS to tags and ADD_DATE to created dates', () => {
    const recs = importExport.parseNetscape(SAMPLE);
    const alpha = recs.find((r) => r.url === 'https://example.com/a');
    expect(alpha.title).toBe('Alpha');
    expect(alpha.tags).toContain('Work');
    expect(alpha.tags).toContain('report');
    expect(alpha.createdAt).toBe(new Date(1600000000 * 1000).toISOString());
  });
});

describe('import into DB', () => {
  it('imports records and preserves dates', () => {
    const res = importExport.importNetscape(SAMPLE);
    expect(res.imported).toBe(3);
    expect(res.skipped).toBe(0);
  });

  it('skips duplicates by normalized key on a second import', () => {
    const res = importExport.importNetscape(SAMPLE);
    expect(res.imported).toBe(0);
    expect(res.skipped).toBe(3);
  });

  it('round-trips through export preserving titles, tags, and dates', () => {
    const html = importExport.exportNetscape();
    expect(html).toContain('HREF="https://example.com/a"');
    expect(html).toContain('Alpha');
    expect(html).toContain('TAGS="Work,report"');
    expect(html).toContain('ADD_DATE="1600000000"');
    // The exported dates round-trip back on re-import.
    const recs = importExport.parseNetscape(html);
    const a = recs.find((r) => r.url === 'https://example.com/a');
    expect(a.createdAt).toBe(new Date(1600000000 * 1000).toISOString());
  });
});

